"""Provider-agnostic LLM adapter supporting Mock, OpenAI, Google Gemini, and Anthropic."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import Any

from backoffice_agent.settings import ConfigManager, Settings, get_settings


@dataclass
class PlannedAction:
    """Structured tool call generated by the planner."""

    action_name: str
    args: dict[str, Any]
    rationale: str


@dataclass
class PlanResult:
    """Domain routing + ordered action plan produced by the LLM."""

    domain: str
    steps: list[PlannedAction]
    reasoning: str


class BackOfficeLLM:
    """Unified interface over Mock LLM or live LangChain chat models (OpenAI/Gemini/Anthropic)."""

    def __init__(
        self,
        settings: Settings | None = None,
        config_manager: ConfigManager | None = None,
    ) -> None:
        self.settings = settings or get_settings()
        self.config_manager = config_manager or ConfigManager()
        self._chat_model: Any | None = None

    def _get_live_chat_model(self) -> Any:
        if self._chat_model is not None:
            return self._chat_model

        provider = self.settings.llm_provider.lower().strip()
        if provider == "openai":
            if not self.settings.openai_api_key:
                raise RuntimeError("OPENAI_API_KEY is required when LLM_PROVIDER=openai.")
            from langchain_openai import ChatOpenAI  # type: ignore

            self._chat_model = ChatOpenAI(
                model=self.settings.llm_model,
                temperature=self.settings.llm_temperature,
                api_key=self.settings.openai_api_key,
            )
        elif provider == "gemini":
            if not self.settings.google_api_key:
                raise RuntimeError("GOOGLE_API_KEY is required when LLM_PROVIDER=gemini.")
            from langchain_google_genai import ChatGoogleGenerativeAI  # type: ignore

            self._chat_model = ChatGoogleGenerativeAI(
                model=self.settings.llm_model or "gemini-2.0-flash",
                temperature=self.settings.llm_temperature,
                google_api_key=self.settings.google_api_key,
            )
        elif provider == "anthropic":
            if not self.settings.anthropic_api_key:
                raise RuntimeError("ANTHROPIC_API_KEY is required when LLM_PROVIDER=anthropic.")
            from langchain_anthropic import ChatAnthropic  # type: ignore

            self._chat_model = ChatAnthropic(
                model=self.settings.llm_model or "claude-3-5-sonnet-latest",
                temperature=self.settings.llm_temperature,
                api_key=self.settings.anthropic_api_key,
            )
        else:
            raise ValueError(f"Unsupported live LLM_PROVIDER: {provider}")
        return self._chat_model

    def plan_request(self, user_request: str, available_tools: dict[str, str]) -> PlanResult:
        """Route a user request to HR/Accounting/Sales and produce an ordered action plan."""
        if self.settings.llm_provider.lower().strip() == "mock":
            return self._mock_plan(user_request)

        model = self._get_live_chat_model()
        rules = self.config_manager.load_rules()
        prompts = self.config_manager.load_prompts()
        org = rules.get("organization", "Acme Operations")
        sys_prompt = prompts.get("system_router", "").format(organization=org)

        tool_catalog = "\n".join(f"- {name}: {desc}" for name, desc in available_tools.items())
        planning_prompt = (
            f"{sys_prompt}\n\n"
            f"Available tools:\n{tool_catalog}\n\n"
            f"User Request: {user_request}\n\n"
            "Respond ONLY with valid JSON matching this schema:\n"
            '{"domain": "hr|accounting|sales", "reasoning": "...", '
            '"steps": [{"action_name": "...", "args": {...}, "rationale": "..."}]}'
        )
        response = model.invoke(planning_prompt)
        content = response.content if hasattr(response, "content") else str(response)
        json_match = re.search(r"\{.*\}", content, re.DOTALL)
        if not json_match:
            return self._mock_plan(user_request)

        parsed = json.loads(json_match.group(0))
        steps = [
            PlannedAction(
                action_name=s["action_name"],
                args=s.get("args", {}),
                rationale=s.get("rationale", ""),
            )
            for s in parsed.get("steps", [])
        ]
        return PlanResult(
            domain=parsed.get("domain", "hr"),
            steps=steps,
            reasoning=parsed.get("reasoning", "Planned via live LLM."),
        )

    def summarize_run(self, user_request: str, domain: str, step_results: list[dict[str, Any]]) -> str:
        """Produce a clean executive summary of what the agent completed or paused."""
        if self.settings.llm_provider.lower().strip() == "mock":
            lines = [f"**Domain:** `{domain.upper()}`", f"**Request:** {user_request}", ""]
            for idx, item in enumerate(step_results, start=1):
                status = item.get("status", "unknown")
                action = item.get("action_name", "")
                msg = item.get("summary", "")
                if status == "awaiting_approval":
                    lines.append(
                        f"{idx}. ⏸️ **{action}** — PAUSED for approval (`{item.get('approval_id')}`): {msg}"
                    )
                elif status == "rejected":
                    lines.append(f"{idx}. ❌ **{action}** — REJECTED by human reviewer: {msg}")
                else:
                    lines.append(f"{idx}. ✅ **{action}** — Completed: {msg}")
            return "\n".join(lines)

        model = self._get_live_chat_model()
        prompt = (
            f"Summarize the following back-office agent execution concisely for an ops manager.\n"
            f"Domain: {domain}\nUser Request: {user_request}\n"
            f"Step Results: {json.dumps(step_results, default=str)}"
        )
        response = model.invoke(prompt)
        return response.content if hasattr(response, "content") else str(response)

    # ------------------------------------------------------------------
    # Deterministic Mock Planner (runs locally with zero API keys)
    # ------------------------------------------------------------------
    def _mock_plan(self, user_request: str) -> PlanResult:
        text = user_request.lower()

        # Helper regexes for extracting IDs, numbers, emails, discounts
        cand_match = re.search(r"(cand-\d+)", user_request, re.IGNORECASE)
        emp_match = re.search(r"(emp-\d+)", user_request, re.IGNORECASE)
        inv_match = re.search(r"(inv-\d{4}-\d+)", user_request, re.IGNORECASE)
        exp_match = re.search(r"(exp-\d+)", user_request, re.IGNORECASE)
        lead_match = re.search(r"(lead-\d+)", user_request, re.IGNORECASE)
        money_match = re.search(r"(?:sgd|\$)\s*([0-9,]+(?:\.\d+)?)", user_request, re.IGNORECASE)
        pct_match = re.search(r"(\d+(?:\.\d+)?)\s*%", user_request)

        extracted_amount = float(money_match.group(1).replace(",", "")) if money_match else None
        extracted_pct = float(pct_match.group(1)) if pct_match else None

        # ---------------- HR ----------------
        if any(k in text for k in ["resume", "résumé", "candidate", "offer", "leave", "policy", "employee", "hr", "onboarding"]):
            steps: list[PlannedAction] = []
            cand_id = cand_match.group(1).upper() if cand_match else "CAND-101"

            if any(k in text for k in ["screen", "resume", "résumé"]):
                steps.append(
                    PlannedAction(
                        action_name="screen_resume",
                        args={"candidate_id": cand_id},
                        rationale="Score candidate résumé against role requirements.",
                    )
                )

            if any(k in text for k in ["policy", "leave", "sick", "hybrid", "wfh", "remote", "maternity", "paternity"]):
                emp_id = emp_match.group(1).upper() if emp_match else "EMP-001"
                steps.append(
                    PlannedAction(
                        action_name="answer_hr_policy",
                        args={"question": user_request, "employee_id": emp_id},
                        rationale="Answer employee policy and leave question using HR handbook & HRIS balance.",
                    )
                )

            if "offer" in text:
                salary = extracted_amount or 120000.0
                steps.append(
                    PlannedAction(
                        action_name="draft_offer_letter",
                        args={
                            "candidate_id": cand_id,
                            "salary": salary,
                            "start_date": "2027-01-04",
                        },
                        rationale="Draft offer letter internally first.",
                    )
                )
                if any(k in text for k in ["send", "email", "deliver", "dispatch"]):
                    steps.append(
                        PlannedAction(
                            action_name="send_offer_letter",
                            args={"candidate_id": cand_id},
                            rationale="Send employment offer externally (requires HR Director approval).",
                        )
                    )

            if any(k in text for k in ["update employee", "employee file", "hris", "promote", "salary raise", "update record"]):
                emp_id = emp_match.group(1).upper() if emp_match else "EMP-001"
                args: dict[str, Any] = {
                    "employee_id": emp_id,
                    "notes": f"Updated via Back-Office Agent: {user_request[:120]}",
                }
                if "salary" in text or "raise" in text or "promote" in text:
                    args["salary"] = extracted_amount or 125000.0
                if "title" in text or "promote" in text:
                    args["title"] = "Staff Software Engineer"
                steps.append(
                    PlannedAction(
                        action_name="update_employee_file",
                        args=args,
                        rationale="Maintain employee HRIS record.",
                    )
                )

            if not steps:
                steps.append(
                    PlannedAction(
                        action_name="answer_hr_policy",
                        args={"question": user_request, "employee_id": "EMP-001"},
                        rationale="Default HR policy assistance.",
                    )
                )
            return PlanResult(domain="hr", steps=steps, reasoning="Routed to HR Operations workflow.")

        # ---------------- ACCOUNTING ----------------
        if any(k in text for k in ["invoice", "expense", "reconcile", "reimburse", "payout", "overdue", "payment", "monthly summary", "financial", "accounting"]):
            steps = []

            if any(k in text for k in ["generate invoice", "create invoice", "new invoice", "bill "]):
                amount = extracted_amount or 4500.0
                steps.append(
                    PlannedAction(
                        action_name="generate_invoice",
                        args={
                            "customer_name": "Merlion Logistics Pte Ltd",
                            "customer_email": "ap@merlionlogistics.sg",
                            "description": "Monthly Automation Retainer - Nov 2026",
                            "amount": amount,
                            "due_date": "2026-12-24",
                        },
                        rationale="Create draft invoice in accounting platform.",
                    )
                )
                if any(k in text for k in ["send", "email", "dispatch"]):
                    steps.append(
                        PlannedAction(
                            action_name="send_invoice",
                            args={"invoice_id": inv_match.group(1).upper() if inv_match else "LATEST"},
                            rationale="Send invoice externally to customer (requires Finance approval).",
                        )
                    )
            elif "send invoice" in text and inv_match:
                steps.append(
                    PlannedAction(
                        action_name="send_invoice",
                        args={"invoice_id": inv_match.group(1).upper()},
                        rationale="Send specified invoice externally.",
                    )
                )

            if any(k in text for k in ["reconcile", "expense"]):
                exp_id = exp_match.group(1).upper() if exp_match else "EXP-501"
                steps.append(
                    PlannedAction(
                        action_name="reconcile_expense",
                        args={"expense_id": exp_id},
                        rationale="Match receipt and reconcile expense claim.",
                    )
                )
                if any(k in text for k in ["reimburse", "payout", "pay out", "disburse", "send money"]):
                    steps.append(
                        PlannedAction(
                            action_name="disburse_expense",
                            args={"expense_id": exp_id},
                            rationale="Initiate outbound reimbursement payout (requires Finance approval).",
                        )
                    )
            elif any(k in text for k in ["reimburse", "payout", "disburse"]):
                exp_id = exp_match.group(1).upper() if exp_match else "EXP-501"
                steps.append(
                    PlannedAction(
                        action_name="disburse_expense",
                        args={"expense_id": exp_id},
                        rationale="Initiate outbound reimbursement payout.",
                    )
                )

            if any(k in text for k in ["overdue", "chase", "reminder", "unpaid"]):
                steps.append(
                    PlannedAction(
                        action_name="chase_overdue_invoices",
                        args={"invoice_id": inv_match.group(1).upper() if inv_match else "INV-2026-002"},
                        rationale="Draft and send external overdue payment reminder (requires approval).",
                    )
                )

            if any(k in text for k in ["monthly summary", "summary", "report", "close month", "financial summary"]):
                steps.append(
                    PlannedAction(
                        action_name="compile_monthly_summary",
                        args={"month": "2026-11"},
                        rationale="Compile monthly financial summary and post to internal Slack.",
                    )
                )

            if not steps:
                steps.append(
                    PlannedAction(
                        action_name="compile_monthly_summary",
                        args={"month": "2026-11"},
                        rationale="Default accounting summary.",
                    )
                )
            return PlanResult(domain="accounting", steps=steps, reasoning="Routed to Accounting Operations workflow.")

        # ---------------- SALES ----------------
        steps = []
        lead_id = lead_match.group(1).upper() if lead_match else "LEAD-301"

        if any(k in text for k in ["crm", "update lead", "log note", "stage", "qualified", "proposal"]):
            new_stage = "proposal" if "proposal" in text else ("qualified" if "qualified" in text else "engaged")
            steps.append(
                PlannedAction(
                    action_name="update_crm_lead",
                    args={
                        "lead_id": lead_id,
                        "stage": new_stage,
                        "note": f"Agent CRM update: {user_request[:140]}",
                    },
                    rationale="Keep CRM lead stage and activity notes current.",
                )
            )

        if any(k in text for k in ["nurture", "outreach", "email lead", "early-stage", "early stage"]):
            steps.append(
                PlannedAction(
                    action_name="draft_nurture_email",
                    args={"lead_id": lead_id, "topic": "Back-office AI automation"},
                    rationale="Draft personalized lead-nurturing email.",
                )
            )
            if any(k in text for k in ["send", "email", "dispatch"]):
                steps.append(
                    PlannedAction(
                        action_name="send_nurture_email",
                        args={"lead_id": lead_id},
                        rationale="Send external nurture email to prospect (requires Sales Manager approval).",
                    )
                )

        if any(k in text for k in ["quote", "proposal", "pricing"]):
            target_lead = lead_match.group(1).upper() if lead_match else "LEAD-302"
            subtotal = extracted_amount or 24000.0
            discount_pct = extracted_pct if extracted_pct is not None else 5.0
            steps.append(
                PlannedAction(
                    action_name="prepare_quote",
                    args={
                        "lead_id": target_lead,
                        "items_summary": "Back-Office AI Agent Annual License (25 seats) + Onboarding",
                        "subtotal": subtotal,
                        "discount_pct": discount_pct,
                    },
                    rationale="Prepare commercial quote with discount check.",
                )
            )
            if any(k in text for k in ["send", "email", "deliver"]):
                steps.append(
                    PlannedAction(
                        action_name="send_quote",
                        args={"quote_id": "LATEST"},
                        rationale="Send quote externally to prospect (requires Sales Director approval).",
                    )
                )

        if any(k in text for k in ["follow-up", "follow up", "followup", "schedule", "reminder"]):
            steps.append(
                PlannedAction(
                    action_name="schedule_followup",
                    args={
                        "lead_id": lead_id,
                        "due_date": "2026-12-01",
                        "topic": "Follow up on automation walkthrough & proposal",
                    },
                    rationale="Schedule internal follow-up task in CRM.",
                )
            )

        if not steps:
            steps.append(
                PlannedAction(
                    action_name="update_crm_lead",
                    args={
                        "lead_id": lead_id,
                        "stage": "engaged",
                        "note": f"Logged inquiry: {user_request[:140]}",
                    },
                    rationale="Default CRM logging.",
                )
            )
        return PlanResult(domain="sales", steps=steps, reasoning="Routed to Sales Operations workflow.")
